summary:
bash: cat << 'EOF' > /tmp/test_next.c
#include <stdio.h>
#include <string.h>

int main() {
    char current[] = "ATAGCCAGTGCCTGATACT";
    char right = 'G';
    char next_kmer[256];

    // C code approach
    strncpy(next_kmer, current + 1, 255);
    next_kmer[255] = '\0';
    next_kmer[17] = right;  // k-mer length is 19, so position 18 (0-indexed)
    next_kmer[18] = '\0';

    printf("next_kmer: %s\n", next_kmer);
    printf("expected:  TAGCCAGTGCCTGATACTG\n");

    // The issue: current has length 19, current+1 has length 18
    // We want to append right to get length 19
    // next_kmer after strncpy(current+1) = "TAGCCAGTGCCTGATACT" (18 chars)
    // We need to set position 18 to right and null-terminate at 19
    printf("strlen of next_kmer after strncpy: %zu\n", strlen(next_kmer));

    // Let me try the correct approach
    char next_kmer2[256];
    int len = strlen(current);
    strncpy(next_kmer2, current + 1, len - 1);
    next_kmer2[len - 1] = right;
    next_kmer2[len] = '\0';
    printf("next_kmer2: %s\n", next_kmer2);

    return 0;
}
EOF
gcc -o /tmp/test_next /tmp/test_next.c && /tmp/test_next

